-- 215: Replace the footer "Our Websites" link list (SG footer CMS block, block_id = 1).
--
-- Old: Tertiary Infotech (x2), Tertiary Courses, Tertiary Robotics.
-- New (9): Tertiary Infotech, Tertiary Courses, Tertiary PEI, Tertiary LMS/TMS,
--          Tertiary Exams, Tertiary Tabcard, Tertiary AI4Kids, Tertiary IoT, Tertiary Training.
--
-- Done as a byte-exact REPLACE() using hex literals so the surrounding block HTML
-- (which contains {{store url=''}} single quotes) is never disturbed, and so the
-- apply.php semicolon splitter is not tripped by the multi-line value.

UPDATE cms_block SET content = REPLACE(content, , ) WHERE block_id = 1;
